/**
 * Applies SQL migrations from db/migrations (generated by drizzle-kit from
 * lib/db/schema.ts and reviewed before commit).
 */
import path from "node:path";
import { migrate as migratePg } from "drizzle-orm/node-postgres/migrator";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";
import type { Db } from "@/lib/db/client";

export const MIGRATIONS_FOLDER = path.resolve(process.cwd(), "db/migrations");

export async function runMigrations(database: Db): Promise<void> {
  await migratePg(database as unknown as NodePgDatabase, { migrationsFolder: MIGRATIONS_FOLDER });
}
